// TestOpenAIToOpenAI_ConvertError verifies error body conversion.
func TestOpenAIToOpenAI_ConvertError(t *testing.T) {
	t.Run("non-json content-type wraps in OpenAI error", func(t *testing.T) {
		headers, body, err := convertErrorOpenAIToOpenAIError(
			map[string]string{
				":status":      "503",
				"content-type": "text/plain",
			},
			bytes.NewBufferString("service not available"),
		)
		require.NoError(t, err)
		require.NotNil(t, headers)
		require.NotNil(t, body)
		var e openai.Error
		require.NoError(t, json.Unmarshal(body, &e))
		require.Equal(t, openAIBackendError, e.Error.Type)
	})

	t.Run("json content-type passthrough", func(t *testing.T) {
		headers, body, err := convertErrorOpenAIToOpenAIError(
			map[string]string{
				":status":      "400",
				"content-type": "application/json",
			},
			bytes.NewBufferString(`{"error":{"message":"bad request"}}`),
		)
		require.NoError(t, err)
		require.Nil(t, headers)
		require.Nil(t, body)
	})
}

